pub mod cmd {
    use futures::{SinkExt, channel::mpsc};
    use crate::{error::SlipstreamResult, pages::RoutablePage};
    pub enum AppCommand {
        Route(Box<dyn RoutablePage>),
        CenterWindow,
    }
    pub struct AppCommandChannel {
        sender: mpsc::Sender<AppCommand>,
    }
    #[automatically_derived]
    impl ::core::clone::Clone for AppCommandChannel {
        #[inline]
        fn clone(&self) -> AppCommandChannel {
            AppCommandChannel {
                sender: ::core::clone::Clone::clone(&self.sender),
            }
        }
    }
    impl AppCommandChannel {
        pub fn new(sender: mpsc::Sender<AppCommand>) -> Self {
            Self { sender }
        }
        pub fn try_route(
            &mut self,
            page_data: Box<dyn RoutablePage>,
        ) -> SlipstreamResult<()> {
            self.sender.try_send(AppCommand::Route(page_data))?;
            Ok(())
        }
        pub async fn route(
            &mut self,
            page_data: Box<dyn RoutablePage>,
        ) -> SlipstreamResult<()> {
            self.sender.send(AppCommand::Route(page_data)).await?;
            Ok(())
        }
        pub fn try_center_window(&mut self) -> SlipstreamResult<()> {
            self.sender.try_send(AppCommand::CenterWindow)?;
            Ok(())
        }
        pub async fn center_window(&mut self) -> SlipstreamResult<()> {
            self.sender.send(AppCommand::CenterWindow).await?;
            Ok(())
        }
    }
}
pub mod config {
    use std::time::Duration;
    pub const FILE_INDENTATION_SIZE: f32 = 8.0;
    pub const LAUNCH_DELAY: Duration = Duration::from_millis(500);
    pub const DEFAULT_SIZE: egui::Vec2 = egui::Vec2::new(800.0, 600.0);
    pub const APP_TITLE: &str = "Slipstream";
    pub fn configure_dark_style() -> egui::Style {
        let style = egui::Theme::Dark.default_style();
        egui::Style {
            visuals: egui::Visuals {
                interact_cursor: Some(egui::CursorIcon::PointingHand),
                window_fill: egui::Color32::from_gray(30),
                widgets: egui::style::Widgets {
                    active: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.active
                    },
                    inactive: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.inactive
                    },
                    hovered: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.hovered
                    },
                    noninteractive: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.noninteractive
                    },
                    open: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.open
                    },
                    ..Default::default()
                },
                panel_fill: egui::Color32::from_gray(40),
                ..Default::default()
            },
            ..Default::default()
        }
    }
    pub fn configure_light_style() -> egui::Style {
        let style = egui::Theme::Light.default_style();
        egui::Style {
            visuals: egui::Visuals {
                interact_cursor: Some(egui::CursorIcon::PointingHand),
                panel_fill: egui::Color32::WHITE,
                widgets: egui::style::Widgets {
                    active: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.active
                    },
                    inactive: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.inactive
                    },
                    hovered: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.hovered
                    },
                    noninteractive: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.noninteractive
                    },
                    open: egui::style::WidgetVisuals {
                        corner_radius: egui::CornerRadius::ZERO,
                        ..style.visuals.widgets.open
                    },
                    ..Default::default()
                },
                ..Default::default()
            },
            ..Default::default()
        }
    }
}
pub mod decorations {
    use crate::{
        cmd::AppCommandChannel, config::APP_TITLE, error::SlipstreamResult, icons::icons,
        pages::{info::InfoPage, settings::SettingsPage},
        shared::GraphicsState,
    };
    pub enum WindowState {
        #[default]
        Normal,
        Maximized,
        Minimized,
    }
    #[automatically_derived]
    impl ::core::fmt::Debug for WindowState {
        #[inline]
        fn fmt(&self, f: &mut ::core::fmt::Formatter) -> ::core::fmt::Result {
            ::core::fmt::Formatter::write_str(
                f,
                match self {
                    WindowState::Normal => "Normal",
                    WindowState::Maximized => "Maximized",
                    WindowState::Minimized => "Minimized",
                },
            )
        }
    }
    #[automatically_derived]
    impl ::core::marker::Copy for WindowState {}
    #[automatically_derived]
    #[doc(hidden)]
    unsafe impl ::core::clone::TrivialClone for WindowState {}
    #[automatically_derived]
    impl ::core::clone::Clone for WindowState {
        #[inline]
        fn clone(&self) -> WindowState {
            *self
        }
    }
    #[automatically_derived]
    impl ::core::marker::StructuralPartialEq for WindowState {}
    #[automatically_derived]
    impl ::core::cmp::PartialEq for WindowState {
        #[inline]
        fn eq(&self, other: &WindowState) -> bool {
            let __self_discr = ::core::intrinsics::discriminant_value(self);
            let __arg1_discr = ::core::intrinsics::discriminant_value(other);
            __self_discr == __arg1_discr
        }
    }
    #[automatically_derived]
    impl ::core::cmp::Eq for WindowState {
        #[inline]
        #[doc(hidden)]
        #[coverage(off)]
        fn assert_fields_are_eq(&self) {}
    }
    #[automatically_derived]
    impl ::core::default::Default for WindowState {
        #[inline]
        fn default() -> WindowState {
            Self::Normal
        }
    }
    impl WindowState {
        pub fn get_state(ui: &egui::Ui) -> Self {
            let states = ui
                .input(|i| {
                    let vp = i.viewport();
                    (vp.maximized, vp.minimized)
                });
            match states {
                (Some(true), _) => Self::Maximized,
                (_, Some(true)) => Self::Minimized,
                _ => Self::Normal,
            }
        }
    }
    /// Renders the double square icon to unmaximize the window.
    pub fn draw_unmaximize(ui: &mut egui::Ui) -> egui::Response {
        let padding = ui.style().spacing.button_padding;
        let icon_size = egui::vec2(10.0, 10.0);
        let total_width = icon_size.x + padding.x * 2.0;
        let total_size = egui::vec2(total_width, ui.available_height());
        let (rect, response) = ui.allocate_exact_size(total_size, egui::Sense::click());
        if ui.is_rect_visible(rect) {
            let painter = ui.painter();
            let visuals = ui.style().interact(&response);
            painter
                .rect(
                    rect,
                    0.0,
                    visuals.weak_bg_fill,
                    visuals.bg_stroke,
                    egui::StrokeKind::Inside,
                );
            let stroke_color = if response.hovered() {
                ui.visuals().widgets.hovered.fg_stroke.color
            } else {
                ui.visuals().widgets.inactive.fg_stroke.color
            };
            let stroke = egui::Stroke::new(1.0, stroke_color);
            let box_size = egui::vec2(8.0, 8.0);
            let back_min = rect.min + egui::vec2(padding.x + 3.0, padding.y + 1.0);
            let back_rect = egui::Rect::from_min_size(back_min, box_size);
            painter.line_segment([back_rect.left_top(), back_rect.right_top()], stroke);
            painter
                .line_segment([back_rect.right_top(), back_rect.right_bottom()], stroke);
            let front_min = rect.min + egui::vec2(padding.x + 0.0, padding.y + 4.0);
            let front_rect = egui::Rect::from_min_size(front_min, box_size);
            painter.rect_filled(front_rect, 0.0, visuals.weak_bg_fill);
            painter.rect_stroke(front_rect, 0.0, stroke, egui::StrokeKind::Middle);
        }
        response
    }
    pub fn draw_version_details(ui: &mut egui::Ui) {
        let screen_rect = ui.viewport_rect();
        let pos = egui::pos2(screen_rect.min.x + 12.0, screen_rect.max.y - 12.0);
        ui.ctx()
            .layer_painter(
                egui::LayerId::new(
                    egui::Order::Foreground,
                    egui::Id::new("version_overlay"),
                ),
            )
            .text(
                pos,
                egui::Align2::LEFT_BOTTOM,
                ::alloc::__export::must_use({
                    ::alloc::fmt::format(
                        format_args!(
                            "v{0} ({1})",
                            "0.1.0",
                            &"fea94ba8f8554ea5774768189ea7a4bb82489688"[..8],
                        ),
                    )
                }),
                egui::FontId::proportional(12.0),
                egui::Color32::from_white_alpha(200),
            );
    }
    /// Draws the background image with a gray overlay.
    pub fn draw_background(bg_image: &egui::Image, ui: &mut egui::Ui) {
        let viewport_rect = ui.ctx().viewport_rect();
        bg_image.paint_at(ui, viewport_rect);
        let bg_overlay = if ui.theme() == egui::Theme::Dark {
            egui::Color32::from_black_alpha(100)
        } else {
            egui::Color32::TRANSPARENT
        };
        ui.painter().rect_filled(viewport_rect, 0.0, bg_overlay);
    }
    /// Draws the title buttons (close, minimize, maximize)
    pub fn draw_title_buttons(ui: &mut egui::Ui) {
        let layout_bg = ui.style().visuals.panel_fill;
        ui.with_layout(
            egui::Layout::right_to_left(egui::Align::Center),
            |ui| {
                let old_hover = ui.visuals().widgets.hovered.weak_bg_fill;
                let old_hover_fill = ui.visuals().widgets.hovered.fg_stroke;
                let red_color = ui.visuals().error_fg_color;
                ui.visuals_mut().widgets.hovered.weak_bg_fill = red_color;
                ui.visuals_mut().widgets.hovered.fg_stroke = egui::Stroke::new(
                    old_hover_fill.width,
                    egui::Color32::WHITE,
                );
                ui.spacing_mut().item_spacing = egui::Vec2::ZERO;
                ui.visuals_mut().widgets.hovered.bg_stroke = egui::Stroke::new(
                    0.0,
                    egui::Color32::BLACK,
                );
                ui.visuals_mut().widgets.active.bg_stroke = egui::Stroke::new(
                    0.0,
                    egui::Color32::BLACK,
                );
                ui.visuals_mut().widgets.inactive.weak_bg_fill = layout_bg;
                ui.spacing_mut().button_padding = egui::vec2(16.0, 8.0);
                let close_button = egui::Button::new(icons::regular::X)
                    .corner_radius(0.0);
                if ui.add(close_button).clicked() {
                    ui.send_viewport_cmd(egui::ViewportCommand::Close);
                }
                ui.visuals_mut().widgets.hovered.weak_bg_fill = old_hover;
                let window_state = WindowState::get_state(ui);
                if window_state == WindowState::Maximized {
                    if draw_unmaximize(ui).clicked() {
                        ui.send_viewport_cmd(egui::ViewportCommand::Maximized(false));
                    }
                } else {
                    let maximize_button = egui::Button::new(icons::regular::SQUARE)
                        .corner_radius(0.0);
                    if ui.add(maximize_button).clicked() {
                        ui.send_viewport_cmd(egui::ViewportCommand::Maximized(true));
                    }
                }
                let minimize_button = egui::Button::new(icons::regular::MINUS)
                    .corner_radius(0.0);
                if ui.add(minimize_button).clicked() {
                    ui.send_viewport_cmd(egui::ViewportCommand::Minimized(true));
                }
            },
        );
    }
    pub fn handle_frameless_resize(ctx: &egui::Context) {
        let border_width = 6.0;
        let screen_rect = ctx.viewport_rect();
        let Some(pointer_pos) = ctx.pointer_interact_pos() else {
            return;
        };
        let on_left = pointer_pos.x <= screen_rect.min.x + border_width;
        let on_right = pointer_pos.x >= screen_rect.max.x - border_width;
        let on_top = pointer_pos.y <= screen_rect.min.y + border_width;
        let on_bottom = pointer_pos.y >= screen_rect.max.y - border_width;
        if !on_left && !on_right && !on_top && !on_bottom {
            return;
        }
        let direction = match (on_left, on_right, on_top, on_bottom) {
            (true, false, false, false) => Some(egui::ResizeDirection::West),
            (false, true, false, false) => Some(egui::ResizeDirection::East),
            (false, false, true, false) => Some(egui::ResizeDirection::North),
            (false, false, false, true) => Some(egui::ResizeDirection::South),
            (true, false, true, false) => Some(egui::ResizeDirection::NorthWest),
            (true, false, false, true) => Some(egui::ResizeDirection::SouthWest),
            (false, true, true, false) => Some(egui::ResizeDirection::NorthEast),
            (false, true, false, true) => Some(egui::ResizeDirection::SouthEast),
            _ => {
                {
                    use ::tracing::__macro_support::Callsite as _;
                    static __CALLSITE: ::tracing::callsite::DefaultCallsite = {
                        static META: ::tracing::Metadata<'static> = {
                            ::tracing_core::metadata::Metadata::new(
                                "event editor\\src\\decorations.rs:200",
                                "mktools::decorations",
                                ::tracing::Level::ERROR,
                                ::tracing_core::__macro_support::Option::Some(
                                    "editor\\src\\decorations.rs",
                                ),
                                ::tracing_core::__macro_support::Option::Some(200u32),
                                ::tracing_core::__macro_support::Option::Some(
                                    "mktools::decorations",
                                ),
                                ::tracing_core::field::FieldSet::new(
                                    &["message"],
                                    ::tracing_core::callsite::Identifier(&__CALLSITE),
                                ),
                                ::tracing::metadata::Kind::EVENT,
                            )
                        };
                        ::tracing::callsite::DefaultCallsite::new(&META)
                    };
                    let enabled = ::tracing::Level::ERROR
                        <= ::tracing::level_filters::STATIC_MAX_LEVEL
                        && ::tracing::Level::ERROR
                            <= ::tracing::level_filters::LevelFilter::current()
                        && {
                            let interest = __CALLSITE.interest();
                            !interest.is_never()
                                && ::tracing::__macro_support::__is_enabled(
                                    __CALLSITE.metadata(),
                                    interest,
                                )
                        };
                    if enabled {
                        (|value_set: ::tracing::field::ValueSet| {
                            let meta = __CALLSITE.metadata();
                            ::tracing::Event::dispatch(meta, &value_set);
                        })({
                            #[allow(unused_imports)]
                            use ::tracing::field::{debug, display, Value};
                            __CALLSITE
                                .metadata()
                                .fields()
                                .value_set_all(
                                    &[
                                        (::tracing::__macro_support::Option::Some(
                                            &format_args!(
                                                "Hmmm, the cursor seems to be at opposite sides of the window at the same time",
                                            ) as &dyn ::tracing::field::Value,
                                        )),
                                    ],
                                )
                        });
                    } else {
                    }
                };
                None
            }
        };
        if let Some(dir) = direction {
            ctx.set_cursor_icon(
                match dir {
                    egui::ResizeDirection::North | egui::ResizeDirection::South => {
                        egui::CursorIcon::ResizeVertical
                    }
                    egui::ResizeDirection::East | egui::ResizeDirection::West => {
                        egui::CursorIcon::ResizeHorizontal
                    }
                    egui::ResizeDirection::NorthEast
                    | egui::ResizeDirection::SouthWest => egui::CursorIcon::ResizeNeSw,
                    egui::ResizeDirection::NorthWest
                    | egui::ResizeDirection::SouthEast => egui::CursorIcon::ResizeNwSe,
                },
            );
            if ctx.input(|i| i.pointer.button_pressed(egui::PointerButton::Primary)) {
                ctx.send_viewport_cmd(egui::ViewportCommand::BeginResize(dir));
            }
        }
    }
    /// Draws a basic title bar with the window title and title buttons.
    pub fn draw_basic_title_bar(ui: &mut egui::Ui) {
        let layout_bg = ui.style().visuals.panel_fill;
        let decorations_id = egui::Id::new("titlebar_panel");
        egui::Panel::top(decorations_id)
            .frame(
                egui::Frame::new()
                    .fill(layout_bg)
                    .inner_margin(egui::Margin::ZERO)
                    .outer_margin(egui::Margin::ZERO),
            )
            .resizable(false)
            .show(
                ui,
                |ui| {
                    let response = ui
                        .interact(
                            ui.ctx().viewport_rect(),
                            decorations_id,
                            egui::Sense::click_and_drag(),
                        );
                    if response.double_clicked() {
                        ui.send_viewport_cmd(egui::ViewportCommand::Maximized(false));
                    }
                    if response.drag_started() {
                        ui.send_viewport_cmd(egui::ViewportCommand::Maximized(false));
                        ui.send_viewport_cmd(egui::ViewportCommand::StartDrag);
                    }
                    ui.horizontal_centered(|ui| {
                        let rect = ui.max_rect();
                        ui.painter()
                            .text(
                                rect.center(),
                                egui::Align2::CENTER_CENTER,
                                APP_TITLE,
                                egui::FontId::proportional(14.0),
                                ui.visuals().text_color(),
                            );
                        draw_title_buttons(ui);
                    })
                },
            );
    }
    pub fn draw_tool_buttons(
        cmd_channel: &mut AppCommandChannel,
        gfx_state: &GraphicsState,
        ui: &mut egui::Ui,
    ) -> SlipstreamResult<()> {
        let egui::InnerResponse { inner, .. } = egui::Area::new(
                egui::Id::new("home_tool_buttons"),
            )
            .anchor(egui::Align2::RIGHT_CENTER, egui::vec2(-10.0, 0.0))
            .show(
                ui,
                |ui| -> SlipstreamResult<()> {
                    let egui::InnerResponse { inner, .. } = ui
                        .vertical(|ui| -> SlipstreamResult<()> {
                            ui.spacing_mut().button_padding = egui::vec2(10.0, 10.0);
                            ui.spacing_mut().item_spacing = egui::vec2(5.0, 5.0);
                            let power_button = egui::Button::new(icons::regular::POWER);
                            if ui
                                .add(power_button)
                                .on_hover_text_at_pointer("Quit")
                                .clicked()
                            {
                                ui.send_viewport_cmd(egui::ViewportCommand::Close);
                            }
                            if ui.theme() == egui::Theme::Dark {
                                if ui
                                    .button(icons::regular::SUN)
                                    .on_hover_text("Switch to light theme")
                                    .clicked()
                                {
                                    ui.ctx().set_theme(egui::Theme::Light);
                                }
                            } else {
                                if ui
                                    .button(icons::regular::MOON)
                                    .on_hover_text("Switch to dark theme")
                                    .clicked()
                                {
                                    ui.ctx().set_theme(egui::Theme::Dark);
                                }
                            }
                            if ui
                                .button(icons::regular::GEAR_FINE)
                                .on_hover_text("Open settings")
                                .clicked()
                            {
                                cmd_channel
                                    .try_route(
                                        SettingsPage::new(cmd_channel.clone(), gfx_state.clone()),
                                    )?;
                            }
                            if ui
                                .button(icons::regular::INFO)
                                .on_hover_text("Open app info")
                                .clicked()
                            {
                                cmd_channel
                                    .try_route(
                                        InfoPage::new(cmd_channel.clone(), gfx_state.clone()),
                                    )?;
                            }
                            if ui
                                .button(icons::regular::GITHUB_LOGO)
                                .on_hover_text("Open the project on GitHub")
                                .clicked()
                            {
                                ui.ctx()
                                    .open_url(egui::OpenUrl {
                                        url: "https://github.com/RadiatedMonkey/mktools".to_owned(),
                                        new_tab: true,
                                    });
                            }
                            Ok(())
                        });
                    inner
                },
            );
        inner
    }
}
